"""Generate the seven-page static website. Run: python3 tools/build_site.py."""
from pathlib import Path
from html import escape
import re
from content import PAGES, FAQ
ROOT=Path(__file__).resolve().parents[1]
def icon(name):return f'<svg class="icon" aria-hidden="true"><use href="#i-{name}"/></svg>'
def expand(text):return re.sub(r'\{\{icon:([a-z]+)\}\}',lambda m:icon(m[1]),text)
def brand(prefix=''):
 return f'<a href="{prefix}index.html" class="brand" aria-label="Sumair Innovations home"><span class="brand-mark" aria-hidden="true"><svg viewBox="0 0 40 40"><path d="M27 9H17a6 6 0 0 0 0 12h6a5 5 0 0 1 0 10H13M28 9 12 31"/></svg></span><span>sumair<span class="brand-sub">INNOVATIONS</span></span></a>'
def header(prefix=''):
 groups=[]
 for kind,label in [('service','Services'),('product','Products')]:
  items=''.join(f'<a href="{prefix}{p["path"]}">{icon(p["icon"])}<span>{escape(p["name"])}</span>{icon("up")}</a>' for p in PAGES if p['kind']==kind)
  groups.append(f'<div class="nav-group"><a href="{prefix}index.html#{label.lower()}">{label}</a><button class="submenu-toggle" aria-label="Show {label.lower()}" aria-expanded="false" aria-controls="{kind}-submenu"><span aria-hidden="true">⌄</span></button><div class="nav-submenu" id="{kind}-submenu">{items}</div></div>')
 return f'<header class="header" id="top"><nav class="nav container" aria-label="Main navigation">{brand(prefix)}<div class="nav-links" id="navigation"><a href="{prefix}index.html">Home</a>{"".join(groups)}<a href="{prefix}index.html#about">About us</a><a href="{prefix}index.html#contact">Contact</a></div><a class="button button-lime nav-contact" href="#contact">Let’s talk {icon("up")}</a><button class="menu-toggle" aria-label="Open navigation" aria-controls="navigation" aria-expanded="false"><span></span><span></span></button></nav></header>'
def footer(prefix=''):
 cols=[]
 for kind,title in [('service','Services'),('product','Our products')]:
  links=''.join(f'<a href="{prefix}{p["path"]}">{escape(p["name"])}</a>' for p in PAGES if p['kind']==kind)
  cols.append(f'<div class="footer-column"><h3>{title}</h3>{links}</div>')
 return f'<footer class="footer"><div class="container"><div class="footer-directory"><div class="footer-story">{brand(prefix)}<p>Your numbers. Your presence. Your growth.<br>One local partner, all the possibilities.</p><a class="footer-whatsapp" href="https://wa.me/917048544134" target="_blank" rel="noopener noreferrer">{icon("chat")} Let’s chat on WhatsApp {icon("up")}</a></div>{"".join(cols)}<div class="footer-column"><h3>Get in touch</h3><a href="tel:+917048544134">+91 70485 44134</a><a href="mailto:info@sumairinnovations.com">info@sumairinnovations.com</a><p>Niwara Housing Society,<br>Kopargaon, Maharashtra</p><a href="{prefix}index.html#faq">Frequently asked questions</a></div></div><div class="footer-bottom"><span>© <span id="year">2026</span> Sumair Innovations. All rights reserved.</span><a href="#top">Back to top {icon("up")}</a><span>Local roots. Limitless possibilities.</span></div></div></footer>'
def faq(questions):
 return ''.join(f'<details {"open" if i==0 else ""}><summary>{escape(q)}<span class="faq-plus" aria-hidden="true"></span></summary><p>{escape(a)}</p></details>' for i,(q,a) in enumerate(questions))
def contact(page=None):
 chosen=page['name'] if page else ''
 options=''.join(f'<option {"selected" if p["name"]==chosen else ""}>{escape(p["name"])}</option>' for p in PAGES)
 title='Good business.<br>Great partnership.<br><em>Let’s talk.</em>' if page is None else 'Your next step.<br><em>Let’s talk.</em>'
 form_title='Let’s arrange your demo.' if page and page['kind']=='product' else 'Tell us a little about you.'
 return f'''<section class="contact-section" id="contact"><div class="container contact-grid"><div class="contact-copy reveal"><p class="eyebrow"><span class="label-line"></span> YOUR NEXT CHAPTER STARTS HERE</p><h2>{title}{icon('star')}</h2><p>Got an idea, a question, or a challenge?<br>Tell us what’s on your mind. We usually reply within a day.</p><div class="contact-details"><a href="tel:+917048544134"><span class="contact-icon">{icon('phone')}</span><span><small>GIVE US A CALL</small><strong>+91 70485 44134</strong></span>{icon('up')}</a><a href="mailto:info@sumairinnovations.com"><span class="contact-icon">{icon('mail')}</span><span><small>DROP A HELLO</small><strong>info@sumairinnovations.com</strong></span>{icon('up')}</a><div><span class="contact-icon">{icon('pin')}</span><span><small>ROOTED RIGHT HERE</small><strong>Niwara Housing Society,<br>Kopargaon, Maharashtra</strong></span></div></div></div>
 <form class="contact-form reveal" id="inquiry-form"><div class="form-title"><h3>{form_title}</h3><p>We’ll take it from here.</p></div><div class="form-row"><div class="field"><label for="name">Your name <span>*</span></label><input id="name" name="name" placeholder="Full name" autocomplete="name" maxlength="100" required></div><div class="field"><label for="phone">Phone number <span>*</span></label><input id="phone" name="phone" type="tel" placeholder="Your contact number" autocomplete="tel" pattern="[+0-9() .\\-]{{7,22}}" minlength="7" maxlength="22" title="Enter a phone number with 7–15 digits; +, spaces, parentheses and hyphens are accepted." required></div></div><div class="field"><label for="service">What can we help with? <span>*</span></label><select id="service" name="service" required><option value="" disabled {"selected" if not chosen else ""}>Select a service</option>{options}<option>Not sure yet — let’s talk</option></select></div><div class="field"><label for="message">A little about your project</label><textarea id="message" name="message" rows="4" maxlength="2000" placeholder="An idea, a challenge, a goal. We’d love to hear it."></textarea></div><button type="submit" class="button form-submit">Continue on WhatsApp {icon('chat')}</button><p class="form-note">{icon('shield')} Opens WhatsApp with your inquiry. Review it before sending.</p><p class="form-status" id="form-status" role="status" hidden></p><p class="form-email">Prefer email? <a href="mailto:info@sumairinnovations.com">Say hello here ↗</a></p></form></div></section>'''
def phone(page):
 tuition=page['key']=='tuition'
 stats='<div><span>Students</span><strong>58</strong></div><div><span>Active batches</span><strong>07</strong></div>' if tuition else '<div><span>Students</span><strong>42</strong></div><div><span>Attendance</span><strong>96<small>%</small></strong></div>'
 if tuition:
  body=f'<div class="phone-section-title">Your batches <span>View all</span></div><div class="batch-row"><span class="batch-icon">10</span><div><strong>Class 10 · Mathematics</strong><small>16 students</small></div>{icon("up")}</div><div class="batch-row"><span class="batch-icon">09</span><div><strong>Class 9 · Science</strong><small>14 students</small></div>{icon("up")}</div><div class="attendance-pill">{icon("check")} Attendance marked. You’re all set.</div>'
 else:
  body=f'<div class="phone-section-title">Quick actions <span>•••</span></div><div class="phone-actions"><span>{icon("users")}Students</span><span>{icon("check")}Hazri</span><span>{icon("tax")}Fees</span></div><div class="phone-section-title">Fee overview <span>This month</span></div><div class="phone-fee"><span>Collection progress<strong>₹18,000 <small>/ ₹24,000</small></strong></span><span>75%</span></div><div class="phone-progress"><span></span></div>'
 bottom=[('grid','Home'),('users','Batches' if tuition else 'Students'),('book' if tuition else 'tax','Marks' if tuition else 'Fees')]
 return f'''<div class="product-art {page['key']}-art" role="img" aria-label="Illustrative {page['name']} app preview with sample data"><div class="product-ring"></div><div class="product-ring outer"></div><span class="floating-feature feature-left">{icon('shield' if tuition else 'check')}{'Google Drive backup' if tuition else 'Daily Hazri, sorted.'}</span><span class="floating-feature feature-right">{icon('book' if tuition else 'chat')}{'English + हिन्दी' if tuition else 'WhatsApp reminders'}</span><div class="phone"><div class="phone-camera"></div><div class="phone-status"><span>9:41</span><span>▂▄▆ ▰</span></div><div class="phone-app-header"><span class="app-icon">{icon('book')}</span><strong>{page['name']}</strong><span class="phone-profile">{'T' if tuition else 'M'}</span></div><div class="phone-body"><small>{'Hello, educator' if tuition else 'Assalamu Alaikum'}</small><h4>{'Ready for a great class?' if tuition else 'A little more organised.'}</h4><div class="phone-stat-row">{stats}</div>{body}<div class="phone-bottom">{''.join(f'<span>{icon(i)}{label}</span>' for i,label in bottom)}</div></div></div><span class="preview-label">ILLUSTRATIVE APP PREVIEW · SAMPLE DATA</span></div>'''
def service_cards():
 items=[]
 for i,p in enumerate(PAGES[:4]):
  items.append(f'<article class="service-card service-{p["key"]} reveal"><div class="card-top"><span class="service-icon">{icon(p["icon"])}</span><span class="card-number">0{i+1} /</span></div><h3>{escape(p.get("cardname",p["name"]))}</h3><p>{escape(p["short"])}</p><ul class="service-tags">{"".join(f"<li>{escape(t)}</li>" for t in p["tags"])}</ul><a class="card-link" href="{p["path"]}">{p["action"]}<span>{icon("up")}</span></a></article>')
 return ''.join(items)
def product_cards():
 return ''.join(f'<article class="product-card theme-{p["key"]} reveal"><div class="product-copy"><span class="product-category"><span></span>{p["kicker"].replace("MADE ","")}</span><h3>{p["name"]}<span>{p["tagline"]}</span></h3><p>{p["short"]}</p><a class="text-link" href="{p["path"]}">Discover the app {icon("up")}</a></div>{phone(p)}<div class="product-footer"><span>Android app</span><span>{"Built for educators, by problem-solvers" if p["key"]=="tuition" else "Designed for everyday simplicity"} {icon("star")}</span></div></article>' for p in PAGES[4:])
def artwork(page):
 key=page['key']
 if page['kind']=='product':return f'<div class="detail-product-art theme-{key}">{phone(page)}<div class="detail-art-caption"><span>ANDROID APP</span><span>{"English + Hindi" if key=="tuition" else "Designed for everyday use"}</span></div></div>'
 if key=='tax':
  content=f'<div class="board-intro"><span class="board-icon">{icon("tax")}</span><div><small>A CLEARER PICTURE</small><h3>Every detail, in order.</h3></div></div><div class="finance-total"><small>Your business essentials</small><strong>Clear. Organised.<br>Accounted for.</strong><div class="finance-line">{"<i></i>"*10}</div></div><div class="board-rows"><span>Income Tax Returns <b>01</b></span><span>GST &amp; bookkeeping <b>02</b></span><span>Planning &amp; support <b>03</b></span></div>'
 elif key=='web':
  content=f'<div class="browser-address">{icon("shield")} YOUR NEXT BIG IDEA</div><div class="browser-site"><div class="browser-logo">{icon("star")} YOUR BRAND <span>Home &nbsp; About &nbsp; Contact</span></div><div class="browser-headline">Made to work.<br><em>Built to stand out.</em></div><p>A digital home for your ambition.</p><span class="browser-button">Discover the possibilities {icon("up")}</span><div class="browser-tiles"><span>{icon("grid")}Websites</span><span>{icon("phone")}Apps</span><span>{icon("code")}Software</span></div></div>'
 elif key=='social':
  content=f'<div class="social-profile"><span>{icon("social")}</span><div><strong>Your brand, online.</strong><small>A voice that feels like you.</small></div>{icon("star")}</div><div class="social-post"><span>YOUR NEXT CHAPTER</span><strong>A brand<br>worth<br><em>knowing.</em></strong>{icon("star")}<small>MEANINGFUL CONTENT. CONSISTENT PRESENCE.</small></div><div class="social-channels"><span>Instagram</span><span>Facebook</span><span>WhatsApp</span></div>'
 else:
  content=f'<div class="board-intro"><span class="board-icon">{icon("chart")}</span><div><small>THE RIGHT PEOPLE. THE RIGHT MESSAGE.</small><h3>Put your business on the map.</h3></div></div><div class="reach-visual"><div class="reach-ring"></div><div class="reach-ring inner"></div><span class="reach-center">{icon("pin")}</span><span class="reach-label reach-local">Local discovery</span><span class="reach-label reach-search">Search</span><span class="reach-label reach-ads">Campaigns</span><span class="reach-label reach-leads">Conversations</span></div><div class="board-bottom">Your audience. Your next opportunity. {icon("up")}</div>'
 return f'<div class="service-art art-{key}" role="img" aria-label="{escape(page["strap"])} — conceptual service illustration"><div class="art-halo"></div><div class="service-board"><div class="board-chrome"><span></span><span></span><span></span><small>THE SUMAIR WAY</small></div>{content}</div><span class="art-floating">{icon("check")} {escape(page["strap"])}</span></div>'
def preview(page):
 tuition=page['key']=='tuition'
 student_panel=f'<div class="preview-stat-grid"><div><span>Students</span><strong>{"58" if tuition else "42"}</strong></div><div><span>{"Batches" if tuition else "Classes"}</span><strong>{"7" if tuition else "4"}</strong></div><div><span>Attendance</span><strong>{"92%" if tuition else "96%"}</strong></div></div><div class="preview-table"><div class="preview-table-head"><span>Student</span><span>{"Batch" if tuition else "Class"}</span><span>Status</span></div>'
 for letter,number in [('A',1),('B',2),('C',1)]:student_panel+=f'<div><span><i>S{letter}</i> Sample student {letter}</span><span>Class {10 if tuition and number==1 else 9 if tuition else number}</span><span class="sample-status">Active</span></div>'
 student_panel+='</div>'
 attendance='<div class="preview-panel-heading"><div><small>YOUR DAILY OVERVIEW</small><h3>Attendance, at a glance.</h3></div><span class="sample-badge">Sample day</span></div><div class="attendance-grid">'+''.join(f'<span class="{"is-absent" if i in [6,19] else ""}">{i:02d}<b>{"A" if i in [6,19] else "P"}</b></span>' for i in range(1,25))+'</div><div class="attendance-legend"><span><i></i> Present</span><span><i></i> Absent</span></div>'
 fees='<div class="preview-stat-grid"><div><span>Sample collection</span><strong>₹18,000</strong></div><div><span>Sample pending</span><strong>₹6,000</strong></div><div><span>Collection progress</span><strong>75%</strong></div></div><div class="preview-collection"><span></span></div><div class="preview-table"><div class="preview-table-head"><span>Student</span><span>Amount</span><span>Status</span></div><div><span>Sample student A</span><span>₹1,000</span><span class="sample-status">Paid</span></div><div><span>Sample student B</span><span>₹1,000</span><span class="sample-status pending">Pending</span></div></div><p class="preview-hint">'+('Keep payment history with your student records.' if tuition else 'Follow up with WhatsApp fee reminders.')+'</p>'
 panels=[('students','Students & batches' if tuition else 'Student records',student_panel),('attendance','Attendance' if tuition else 'Daily Hazri',attendance),('fees','Fees & reminders',fees)]
 if tuition:panels.append(('reports','Marks & reports',f'<div class="preview-panel-heading"><div><small>A CLEAR VIEW OF THEIR PROGRESS</small><h3>Marks &amp; report cards.</h3></div>{icon("book")}</div><div class="preview-table"><div class="preview-table-head"><span>Subject</span><span>Sample marks</span><span>Out of</span></div><div><span>Mathematics</span><span>42</span><span>50</span></div><div><span>Science</span><span>45</span><span>50</span></div><div><span>English</span><span>40</span><span>50</span></div></div><p class="preview-hint">Keep test marks and report cards alongside your class records.</p>'))
 tabs=''.join(f'<button role="tab" id="tab-{key}" aria-selected="{str(i==0).lower()}" aria-controls="panel-{key}" tabindex="{0 if i==0 else -1}">{label}</button>' for i,(key,label,content) in enumerate(panels))
 bodies=''.join(f'<div role="tabpanel" id="panel-{key}" aria-labelledby="tab-{key}" tabindex="0" {"hidden" if i else ""}>{content}</div>' for i,(key,label,content) in enumerate(panels))
 return f'<section class="section product-tour container" id="preview"><div class="section-heading"><div><p class="eyebrow"><span class="label-line"></span> TAKE A LOOK AROUND</p><h2>Everything in its place.<br><em>A simpler everyday.</em></h2></div><p class="section-description">Explore this interactive feature illustration. These are sample records, not a live account or actual app screenshots.</p></div><div class="preview-workspace"><div class="preview-workspace-heading">{icon("book")}<strong>{page["name"]}</strong><span>FEATURE ILLUSTRATION</span></div><div class="preview-layout"><div class="preview-tabs" role="tablist" aria-label="Product features">{tabs}</div><div class="preview-panels">{bodies}</div></div><p class="preview-disclaimer">Illustrative interface · Sample data · Request a live demo to see the actual Android app.</p></div></section>'
def detail(page):
 product=page['kind']=='product'
 hero=f'<section class="page-hero"><div class="container"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="../index.html">Home</a><span>/</span><a href="../index.html#{"products" if product else "services"}">{"Products" if product else "Services"}</a><span>/</span><span aria-current="page">{escape(page["name"])}</span></nav><div class="page-hero-grid"><div class="page-hero-copy"><p class="eyebrow"><span class="status-dot"></span>{page["kicker"]}</p><h1>{page["title"]}</h1><p class="page-lead">{escape(page["intro"])}</p><div class="page-actions"><a class="button button-lime" href="#contact">{"Request a demo" if product else "Book a free consultation"} {icon("up")}</a><a class="text-link" href="#{"preview" if product else "included"}">{"Explore the app" if product else "See what’s included"} {icon("arrow")}</a></div><p class="page-assurance">{icon("check")} {"Android app · Personal setup guidance" if product else "Clear scope · Personal support · One local team"}</p></div>{artwork(page)}</div></div></section>'
 features=''.join(f'<article class="detail-feature"><span class="detail-feature-icon">{icon(i)}</span><h3>{escape(title)}</h3><p>{escape(body)}</p></article>' for title,body,i in page['features'])
 audience=''.join(f'<li>{icon("check")}<span>{escape(item)}</span></li>' for item in page['audience'])
 prepare=''.join(f'<div class="detail-next-step"><span>0{i+1}</span><p>{escape(item)}</p></div>' for i,item in enumerate(page['prepare']))
 related=''.join(f'<a href="../{p["path"]}" class="related-link">{icon(p["icon"])}<span>{escape(p["name"])}</span>{icon("up")}</a>' for p in PAGES if p['kind']==page['kind'] and p['key']!=page['key'])
 return f'''{hero}<div class="detail-value-band"><div class="container"><span>{icon(page['icon'])}{escape(page['name'])}</span><strong>{escape(page['strap'])}</strong><a href="#contact">{'Arrange a demo' if product else 'Discuss your requirements'} {icon('arrow')}</a></div></div>
 <section class="section container" id="included"><div class="section-heading"><div><p class="eyebrow"><span class="label-line"></span>{'BUILT AROUND YOUR EVERYDAY' if product else 'THE DETAILS THAT MAKE A DIFFERENCE'}</p><h2>{'One app.<br><em>So much more organised.</em>' if product else 'The support you need.<br><em>All in one place.</em>'}</h2></div><p class="section-description">{'Explore the features designed to make your daily administration easier.' if product else 'Choose the help your business needs. We’ll agree on the exact scope and quote before getting started.'}</p></div><div class="detail-feature-grid">{features}</div></section>{preview(page) if product else ''}
 <section class="detail-fit-section"><div class="container detail-fit-grid"><div><p class="eyebrow"><span class="label-line"></span>{'WHO IT’S FOR' if product else 'IS THIS FOR YOU?'}</p><h2>{'Built for the way<br><em>you work.</em>' if product else 'For the people<br><em>making things happen.</em>'}</h2><ul class="audience-list">{audience}</ul></div><div class="detail-next"><span class="next-kicker">A SIMPLE PLACE TO START</span><h3>{'Let’s show you around.' if product else 'Let’s get to know your needs.'}</h3>{prepare}<a class="text-link" href="#contact">{'Request your demo' if product else 'Start the conversation'} {icon('up')}</a></div></div></section>
 <section class="faq-section section container" id="faq"><div class="faq-intro"><p class="eyebrow"><span class="label-line"></span> GOOD TO KNOW</p><h2>Your questions.<br><em>Straight answers.</em></h2><p>Need a little more detail?<br>We’re happy to help.</p><a class="text-link" href="#contact">Ask us anything {icon('up')}</a></div><div class="faq-list">{faq(page['questions'])}</div></section>
 {contact(page)}<section class="related-section container"><div><p class="eyebrow">{'MORE FROM SUMAIR' if product else 'ONE TEAM. MORE POSSIBILITIES.'}</p><h2>{'Explore our other app.' if product else 'What else can we help with?'}</h2></div><div class="related-links">{related}</div></section>'''
def document(body,title,description,prefix='',classes='home-page',path='index.html'):
 return f'''<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#102e25"><meta name="description" content="{escape(description,quote=True)}"><title>{escape(title)}</title><link rel="icon" href="{prefix}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{prefix}assets/styles.css"></head>
<body class="{classes}" data-page-path="{path}">{(ROOT/'templates/icons.html').read_text()}<a class="skip-link" href="#main">Skip to content</a>{header(prefix)}<main id="main">{expand(body)}</main>{footer(prefix)}<script src="{prefix}assets/script.js"></script></body></html>'''
def build():
 home=(ROOT/'templates/home.html').read_text()
 for key,value in {'globe':(ROOT/'templates/globe.html').read_text(),'service_cards':service_cards(),'product_cards':product_cards(),'faq':faq(FAQ),'contact':contact()}.items():home=home.replace('{{'+key+'}}',value)
 (ROOT/'index.html').write_text(document(home,'Sumair Innovations — A little local. A lot of possibility.','One local team for tax & accounting, web development, social media and digital marketing. Sumair Innovations, Kopargaon.'))
 for p in PAGES:
  path=ROOT/p['path'];path.parent.mkdir(exist_ok=True)
  path.write_text(document(detail(p),p['name']+' | Sumair Innovations, Kopargaon',p['intro'],'../','detail-page theme-'+p['key'],p['path']))
 print('Built homepage and six complete detail pages.')
if __name__=='__main__':build()
